// Names Foundation already defines at file scope on Apple platforms, limited to
// the shape of a Dart type name (`Xxx…`). A file that imports Foundation cannot
// declare a C type with one of them, so the generated bridge renames
// Foundation's while it imports it.
//
// Taken from the Xcode 27.2 SDKs. Every identifier of that shape in the
// preprocessed `Foundation/Foundation.h` was declared after the import as
// `typedef struct { double x; } <name>;`, and the ones clang rejected were kept.

/// Built into Objective-C itself, so renaming it around the import does not help.
const foundationNamesNotRenamable = <String>{'Protocol'};

/// True for a name the bridge has to rename, and can.
bool isRenamableFoundationName(String name) =>
    !foundationNamesNotRenamable.contains(name) && (foundationNamesIos.contains(name) || foundationNamesMacosOnly.contains(name));

